SELECT date_trunc('day', bill_ts)::date d, unit_price, count(*) n, sum(qty) units
FROM store.pos_lines WHERE sku_scanned='ATTA-WW-5KG'
GROUP BY 1,2 ORDER BY 1,2;

SELECT sku_scanned, count(DISTINCT unit_price) n_prices, min(unit_price) min_p, max(unit_price) max_p,
       array_agg(DISTINCT unit_price) prices
FROM store.pos_lines GROUP BY 1 ORDER BY 1;

SELECT tender, till_status, count(*) n, count(distinct bill_id) bills
FROM payments.pos_payments
GROUP BY 1,2 ORDER BY 1,2;

